const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Taklimakan Desert region
  const desert = ee.Geometry.Rectangle([82.5, 37.5, 91.5, 41.5]);

  // February 2020
  const col2020 = ee.ImageCollection('MODIS/061/MCD19A2_GRANULES')
    .filterDate('2020-02-01', '2020-02-29')
    .filterBounds(desert)
    .select('Optical_Depth_047');

  // February 2019
  const col2019 = ee.ImageCollection('MODIS/061/MCD19A2_GRANULES')
    .filterDate('2019-02-01', '2019-02-29')
    .filterBounds(desert)
    .select('Optical_Depth_047');

  const size2020 = col2020.size().getInfo();
  const size2019 = col2019.size().getInfo();

  print(`Feb 2020 Images: ${size2020}, Feb 2019 Images: ${size2019}`);

  if (size2020 === 0 || size2019 === 0) {
    print("Insufficient data for one or both years.");
    print("C1");
    return;
  }

  // Compute mean AOD for each period
  const mean2020 = col2020.mean().reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: desert,
    scale: 1000,
    maxPixels: 1e9
  }).get('Optical_Depth_047').getInfo();

  const mean2019 = col2019.mean().reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: desert,
    scale: 1000,
    maxPixels: 1e9
  }).get('Optical_Depth_047').getInfo();

  print(`Feb 2020 AOD: ${(mean2020 || 0).toFixed(3)}`);
  print(`Feb 2019 AOD: ${(mean2019 || 0).toFixed(3)}`);

  if (mean2020 === null || mean2019 === null || isNaN(mean2020) || isNaN(mean2019)) {
    print("C3");
    return;
  }

  if (mean2020 > mean2019) {
    print("A");
  } else {
    print("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
